export class ConnectPatients extends APIResource {

  /**
   * Search patients in the target system
   *
   * `GET /v1/connect/connections/{connection_id}/patients`, scope `connect.read`, verb `patient.search`, answers hold patient data, metered as `connect.read`.
   */
  search(connectionId: string, query: C.PatientsSearchQuery, options?: RequestOptions): PagePromise<C.Patient, C.PatientList> {
    return this._client.requestPage<C.Patient, C.PatientList>(OPERATIONS["connect.patients.search"], { path: { connection_id: connectionId }, query }, options);
  }

  /**
   * Read one patient
   *
   * The patient as the system holds it. Answered by the system through the site's hub; nothing is stored. Check `capabilities.get` first: `partial` names its `limits`. 403 `forbidden` with `reason: needs_kontext`: the system answers only for the patient open in it (MEDICAL OFFICE, QUINCY, T2med); the message names the person's step, and the same call works after it. The same answer comes for another patient than the open one and for an export file older than the connection allows. 404 `not_found`: the system has no such record. 422 `verb_unsupported` or `verb_unverified`: the connection cannot run the verb. 503 `agent_offline`: the hub is offline.
   *
   * `GET /v1/connect/connections/{connection_id}/patients/{patient_id}`, scope `connect.read`, verb `patient.read`, answers hold patient data, metered as `connect.read`.
   */
  get(connectionId: string, patientId: string, query: C.PatientsGetQuery, options?: RequestOptions): Promise<C.Patient> {
    return this._client.request<C.Patient>(OPERATIONS["connect.patients.get"], { path: { connection_id: connectionId, patient_id: patientId }, query }, options);
  }

  /**
   * Read the insurance of a patient
   *
   * The insurer of the patient. MEDICAL OFFICE: statutory insurers only (`limits: statutory_only`). Answered by the system through the site's hub; nothing is stored. Check `capabilities.get` first: `partial` names its `limits`. 403 `forbidden` with `reason: needs_kontext`: the system answers only for the patient open in it (MEDICAL OFFICE, QUINCY, T2med); the message names the person's step, and the same call works after it. The same answer comes for another patient than the open one and for an export file older than the connection allows. 404 `not_found`: the system has no such record. 422 `verb_unsupported` or `verb_unverified`: the connection cannot run the verb. 503 `agent_offline`: the hub is offline.
   *
   * `GET /v1/connect/connections/{connection_id}/patients/{patient_id}/coverage`, scope `connect.read`, verb `patient.insurance`, answers hold patient data, metered as `connect.read`.
   */
  getCoverage(connectionId: string, patientId: string, query: C.PatientsGetCoverageQuery, options?: RequestOptions): Promise<C.Coverage> {
    return this._client.request<C.Coverage>(OPERATIONS["connect.patients.getCoverage"], { path: { connection_id: connectionId, patient_id: patientId }, query }, options);
  }
}

